/* the season's arrivals, recorded when the season is made: the rookies the last season's end brought (the players made to fill the tiers when a career starts are not arrivals) */
function m3Arrivals(C,D0){const was=C.season-1,nm=new Set(D0&&D0.rookies||[]);C.cur.arr=C.players.filter(p=>p.nw===was&&p.ret==null&&nm.has(p.name)).map(p=>p.id)}
